// Change this passcode in n8n only. Keep CHANGE_ME in the copy committed to Git.
const ADMIN_PASSCODE = 'CHANGE_ME';

const body = $('Admin Webhook').first().json.body || {};

if (String(body.adminPasscode || '') !== ADMIN_PASSCODE) {
  return [{ json: { statusCode: 401, errors: ['Invalid admin passcode.'] } }];
}

const errors = [];
const name = String(body.name || '').trim();
const price = Number(body.price);
const category = String(body.category || '').trim();
const description = String(body.description || '').trim();
const photos = Array.isArray(body.photoUrls) ? body.photoUrls.map(String) : [];

if (name.length < 2 || name.length > 80) errors.push('Item name is required (2-80 characters).');
if (!Number.isFinite(price) || price <= 0 || price > 100000) errors.push('Price must be a positive number.');
if (category.length < 1 || category.length > 40) errors.push('Category is required.');
if (description.length > 300) errors.push('Description is too long (max 300 characters).');
if (photos.length < 1 || photos.length > 8) errors.push('Provide 1-8 photo URLs.');
if (!photos.every(u => /^https:\/\//.test(u))) errors.push('Every photo must be an https URL.');

if (errors.length > 0) {
  return [{ json: { statusCode: 400, errors } }];
}

const itemId = 'item-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 4);

// Field names below = columns of the menu_items Data Table
return [{ json: {
  itemId,
  name,
  price,
  category,
  description,
  imageUrl: photos[0],
  photoUrls: JSON.stringify(photos),
  modelUrl: '',
  modelStatus: 'none',
  active: true
} }];
